-- Backend Engineering ("The Fracture") Act 19 -- "Backend Security" content.
-- Opens Arc V (Protect & Prove). 1 campaign, 2 operations, 12 missions (11 lessons + boss),
-- following the same campaigns -> operations -> missions -> dialogue -> objectives ->
-- challenges -> hints pattern as every prior Act.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-be19', 'world-be-19', 'backend-security', '19A - Backend Security', 'An external security review finds ordinary security debt on a public API -- unvalidated input, permissive CORS, no rate limiting. Arc V opens with fixing it, and with a discovery in the server logs that Mira can''t stop thinking about.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-be19-1', 'campaign-be19', 'threats-and-trust-boundaries', 'Threats and Trust Boundaries', 'Threat modelling, input validation, SQL and NoSQL injection, CORS and CSRF -- the trust boundaries a backend engineer is actually responsible for.', 1),
  ('operation-be19-2', 'campaign-be19', 'hardening-the-perimeter', 'Hardening the Perimeter', 'SSRF awareness, secure headers, rate limiting, brute-force protection, dependency and secret security, and the external review that finds all of it at once.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-be19-01', 'world-be-19', 'campaign-be19', 'operation-be19-1', 'threat-modelling', 'Threat Modelling', 'Arc V opens with a question Forge has never had to ask out loud: not "does this work," but "what happens if someone tries to make it fail on purpose." A routine external security review is about to answer for us if we don''t ask first.', 'advanced', ARRAY['mira','forge'], null, null, '{"type":"simulation","simulationId":"threat-modelling-sim"}'::jsonb, '{"xp":225,"credits":43}'::jsonb, false, 1),
  ('mission-be19-02', 'world-be-19', 'campaign-be19', 'operation-be19-1', 'input-validation', 'Input Validation', 'Every attack this Act covers starts the same way: data crossing a trust boundary without anyone checking what it actually is. Validation at the edge is the cheapest fix available, and the one most often skipped.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be19-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"input-validation-sim"}'::jsonb, '{"xp":227,"credits":43}'::jsonb, false, 2),
  ('mission-be19-03', 'world-be-19', 'campaign-be19', 'operation-be19-1', 'sql-injection-prevention', 'SQL Injection Prevention', 'A query built by concatenating user input into a string isn''t really one query -- it''s an invitation to write a different one. Parameterized queries close that door for good.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be19-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"sql-injection-prevention-sim"}'::jsonb, '{"xp":229,"credits":44}'::jsonb, false, 3),
  ('mission-be19-04', 'world-be-19', 'campaign-be19', 'operation-be19-1', 'nosql-injection-awareness', 'NoSQL Injection Awareness', 'A relational query breaks loudly on a stray quote. A document-database query breaks a different way: it just accepts a whole operator object where it expected a plain value, and quietly does something the developer never intended.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be19-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"nosql-injection-sim"}'::jsonb, '{"xp":231,"credits":44}'::jsonb, false, 4),
  ('mission-be19-05', 'world-be-19', 'campaign-be19', 'operation-be19-1', 'cors', 'CORS', 'The browser''s same-origin policy is the thing keeping one site from silently reading another''s responses. CORS is Forge deciding, on purpose, exactly which origins get an exception to that rule -- and "all of them" is not a decision, it''s the absence of one.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be19-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"cors-sim"}'::jsonb, '{"xp":233,"credits":44}'::jsonb, false, 5),
  ('mission-be19-06', 'world-be-19', 'campaign-be19', 'operation-be19-1', 'csrf', 'CSRF', 'A browser sends cookies with every request to a site automatically, whether the tab that triggered it meant to or not. CSRF protection is what stops that automatic behavior from turning into a state change nobody asked for.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be19-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"csrf-sim"}'::jsonb, '{"xp":235,"credits":45}'::jsonb, false, 6),
  ('mission-be19-07', 'world-be-19', 'campaign-be19', 'operation-be19-2', 'ssrf-awareness', 'SSRF Awareness', 'Any feature where the backend fetches a URL a user supplied is a feature where the backend can be tricked into fetching somewhere it never meant to go -- including itself.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be19-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"ssrf-awareness-sim"}'::jsonb, '{"xp":237,"credits":45}'::jsonb, false, 7),
  ('mission-be19-08', 'world-be-19', 'campaign-be19', 'operation-be19-2', 'secure-headers', 'Secure Headers', 'A handful of response headers, set once, close off entire categories of attack before a browser even finishes rendering the page.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be19-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"secure-headers-sim"}'::jsonb, '{"xp":239,"credits":45}'::jsonb, false, 8),
  ('mission-be19-09', 'world-be-19', 'campaign-be19', 'operation-be19-2', 'rate-limiting', 'Rate Limiting', 'An endpoint with no limit on how often it can be called isn''t just slow under load -- it''s an open invitation to brute force, scrape, or flood it, one request at a time, forever.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be19-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"rate-limiting-sim"}'::jsonb, '{"xp":241,"credits":46}'::jsonb, false, 9),
  ('mission-be19-10', 'world-be-19', 'campaign-be19', 'operation-be19-2', 'brute-force-protection', 'Brute-Force Protection', 'Rate limiting slows down volume. Brute-force protection is the more specific defense: locking out a repeated-guessing pattern, and never letting an error message tell an attacker which half of a guess was right.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be19-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"brute-force-protection-sim"}'::jsonb, '{"xp":243,"credits":46}'::jsonb, false, 10),
  ('mission-be19-11', 'world-be-19', 'campaign-be19', 'operation-be19-2', 'dependency-and-secret-security', 'Dependency and Secret Security', 'Half of Forge''s attack surface was never written by Forge at all -- it was pulled in as a dependency. The other half is one hardcoded key away from being handed out for free.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be19-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"dependency-secret-security-sim"}'::jsonb, '{"xp":245,"credits":47}'::jsonb, false, 11),
  ('mission-be19-12', 'world-be-19', 'campaign-be19', 'operation-be19-2', 'the-exposed-api', 'The Exposed API', 'An external security review found exactly the kind of debt every team accumulates -- unvalidated input, permissive CORS, no rate limiting. Fixing it is the easy part. What fixing the CORS hole surfaces in the logs is not.', 'boss', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be19-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"exposed-api-boss-sim"}'::jsonb, '{"xp":545,"credits":125,"badgeIds":["exposed-api"],"skillXp":{"backend_security":30}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-be19-01', 1, 'mira', 'Arc IV proved every piece works in isolation. Arc V asks whether any of it survives contact with real conditions -- starting with a question we''ve mostly skipped: what happens when someone tries to make this fail on purpose, not by accident.'),
  ('mission-be19-01', 2, 'forge', 'A security firm just ran an external review against one of our public APIs. I haven''t seen the full findings yet. I''ve seen enough of the summary to know we''re not going to like it.'),
  ('mission-be19-01', 3, 'mira', 'Before we open that report, learn to do what they did first: think like someone whose job is to break this, not ship it. Threat modelling isn''t a checklist, it''s one habit -- for every piece of trust this system extends, ask what happens if that trust is abused.'),

  ('mission-be19-02', 1, 'forge', 'Every attack this Act covers starts the same way: data crosses a trust boundary and nobody checked what it actually was before using it. Validation at the edge, before anything downstream touches it, is the cheapest fix on the whole list.'),
  ('mission-be19-02', 2, 'mira', 'Allowlist what''s valid, don''t denylist what you''ve thought of so far -- you''ll never think of everything, and an attacker only needs one thing you didn''t.'),

  ('mission-be19-03', 1, 'mira', 'A query built by string concatenation with user input in it isn''t one query anymore -- it''s an invitation for that input to become part of the query''s own logic.'),
  ('mission-be19-03', 2, 'forge', 'A parameterized query keeps that boundary hard. The database always treats a bound parameter as data, never as SQL, no matter what value happens to be in it.'),

  ('mission-be19-04', 1, 'forge', 'A relational query breaks loudly on a stray quote. A document-database query fails quieter: if a field expects a plain string and instead gets a whole operator object, some drivers just accept it, and the query means something completely different.'),
  ('mission-be19-04', 2, 'mira', 'A login check comparing a password field directly against whatever JSON the client sent is the classic case. Send an operator object instead of a real password and the query can silently mean something true for every account, not just one.'),

  ('mission-be19-05', 1, 'mira', 'CORS exists because the browser''s same-origin policy would otherwise block every legitimate cross-origin request too. A CORS header is Forge deciding, on purpose, which origins get an exception -- and it has to be a decision, not a default.'),
  ('mission-be19-05', 2, 'forge', 'Allowing every origin looks harmless until you pair it with allowing credentials too. At that point you''ve told every website on the internet it''s allowed to make authenticated requests to this API using a logged-in user''s own cookies.'),

  ('mission-be19-06', 1, 'forge', 'A browser attaches a site''s cookies to every request to that site automatically -- including one triggered by a form on a completely different website the user happened to have open in another tab.'),
  ('mission-be19-06', 2, 'mira', 'CSRF protection is what breaks that automatic trust: a token the attacker''s page can''t read, or a same-site cookie policy that refuses to send the cookie on a cross-site request in the first place.'),

  ('mission-be19-07', 1, 'mira', 'Any feature where the backend itself fetches a URL supplied by a user -- a webhook target, an image-by-URL upload -- is a feature where the backend can be pointed somewhere it never meant to go.'),
  ('mission-be19-07', 2, 'forge', 'Including its own internal network. A cloud metadata endpoint, an internal admin panel, a database only meant to be reachable from inside our own network -- from the backend''s perspective, a URL is just a URL, unless something explicitly tells it not to trust one.'),

  ('mission-be19-08', 1, 'forge', 'A handful of response headers, set once, close off entire categories of attack before the browser even finishes rendering the page. None of them touch business logic -- they just tell the browser to stop trusting certain things by default.'),
  ('mission-be19-08', 2, 'mira', 'Small, cheap, easy to forget. Exactly the kind of finding an external review turns up in bulk.'),

  ('mission-be19-09', 1, 'mira', 'An endpoint with no limit on how often it can be called isn''t just a performance risk -- it''s an open invitation to brute-force a password, scrape an entire dataset, or flood a queue, one request at a time, forever.'),
  ('mission-be19-09', 2, 'forge', 'The external review''s simplest finding: none of our public endpoints have any rate limit configured at all. Not the login endpoint. Not the search endpoint. None of them.'),

  ('mission-be19-10', 1, 'forge', 'Rate limiting slows down volume across the board. Brute-force protection is narrower and more specific: recognizing a repeated-guessing pattern against one account, and refusing to make it easy.'),
  ('mission-be19-10', 2, 'mira', 'The other half of it is quieter: never let an error message tell an attacker which part of their guess was right. "No account found" followed later by "incorrect password" hands over a working username for free.'),

  ('mission-be19-11', 1, 'mira', 'Half of Forge''s attack surface was never written by Forge at all -- it arrived as a dependency, with whatever vulnerabilities it shipped with, some of them known and unpatched for months.'),
  ('mission-be19-11', 2, 'forge', 'The other half is simpler and somehow still more common: a real credential, committed straight into source control, sitting in plain text in a file that''s been in git history since before either of us started.'),

  ('mission-be19-12', 1, 'forge', 'Full findings are in. Three real issues, all ordinary: an endpoint accepting any status string with no validation, a CORS policy that reflects any origin back with credentials enabled, and no rate limiting anywhere on the public API surface.'),
  ('mission-be19-12', 2, 'mira', 'None of that is the pattern. It''s exactly what it looks like -- security debt every team accumulates when nobody''s looking at it from outside. Fix it like debt: triage, prioritize, patch.'),
  ('mission-be19-12', 3, 'forge', 'All three patched. Rate limiting''s live, CORS now checks against an actual allowlist, status values are validated against the fixed set they were always supposed to be.'),
  ('mission-be19-12', 4, 'forge', 'Fixing the CORS hole meant pulling the request logs to confirm nothing legitimate got blocked by the new allowlist. That''s when I found something else in them.'),
  ('mission-be19-12', 5, 'forge', 'Months of it. Automated requests, steady and low-volume enough that nothing ever alerted on it, hitting this API from outside our network the entire time. Every single one aimed at an endpoint whose path contains a doubled slash.'),
  ('mission-be19-12', 6, 'mira', 'Say that again, slowly. Outside our network.'),
  ('mission-be19-12', 7, 'forge', 'Outside. Not Forge, not a partner integration, not anything in our own infrastructure. Something out there has been probing, specifically, for exactly the pattern we''ve been quietly finding inside our own systems for an Arc and a half.'),
  ('mission-be19-12', 8, 'mira', 'I don''t know what that is. I don''t know if it''s deliberate, or automated, or something that just happened to converge on the same shape we did. I''m not going to guess out loud -- not with something this thin to go on.'),
  ('mission-be19-12', 9, 'forge', 'Agreed. What we actually have: probing traffic, aimed at a specific pattern, coming from outside. That''s it. That''s all we know, and it''s already more than we knew this morning.'),
  ('mission-be19-12', 10, 'mira', 'Before we chase that any further, we need to know what we''ve built actually survives contact with reality -- real file sizes, real load, real production conditions. That question doesn''t wait for us to figure out who''s on the other end of those logs.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-be19-01-o1', 'mission-be19-01', 1, 'Threat-model the endpoint', 'Find the evidence that identifies the actual threat this endpoint failed to model, not just where it eventually showed up.'),
  ('mission-be19-02-o1', 'mission-be19-02', 1, 'Find the missing validation', 'Debug a handler that passes request data straight into business logic with no checks at all.'),
  ('mission-be19-03-o1', 'mission-be19-03', 1, 'Find the injection point', 'Debug a query built by concatenating user input directly into SQL.'),
  ('mission-be19-03-o2', 'mission-be19-03', 2, 'Choose the actual fix', 'Choose the change that prevents this class of injection, not just this one instance of it.'),
  ('mission-be19-04-o1', 'mission-be19-04', 1, 'Find the NoSQL injection point', 'Debug a query that lets an operator object stand in for a plain value.'),
  ('mission-be19-05-o1', 'mission-be19-05', 1, 'Find the CORS misconfiguration', 'Debug a CORS policy that grants an exception it never should have.'),
  ('mission-be19-05-o2', 'mission-be19-05', 2, 'Diagnose the reflection bug', 'Find the evidence that explains the actual mechanism letting an arbitrary origin through.'),
  ('mission-be19-06-o1', 'mission-be19-06', 1, 'Identify the CSRF gap', 'Choose the actual gap in an endpoint that trusts a session cookie alone.'),
  ('mission-be19-07-o1', 'mission-be19-07', 1, 'Diagnose the SSRF root cause', 'Find the evidence that is the actual root cause enabling this, not just proof it''s exploitable.'),
  ('mission-be19-08-o1', 'mission-be19-08', 1, 'Match the header to what it prevents', 'Match each secure header to the category of attack it closes off.'),
  ('mission-be19-09-o1', 'mission-be19-09', 1, 'Diagnose the missing rate limit', 'Find the evidence that explains the actual root cause behind unrestricted request volume.'),
  ('mission-be19-09-o2', 'mission-be19-09', 2, 'Find the coverage gap', 'Debug a rate-limiting setup that misses the most sensitive route.'),
  ('mission-be19-10-o1', 'mission-be19-10', 1, 'Find the enumeration leak', 'Debug a login flow that reveals which half of a login guess was correct.'),
  ('mission-be19-11-o1', 'mission-be19-11', 1, 'Find the hardcoded secret', 'Debug a client configuration that commits a live credential to source.'),
  ('mission-be19-11-o2', 'mission-be19-11', 2, 'Diagnose the exploitable dependency', 'Find the evidence that explains why a known vulnerability is actually exploitable here, not just present.'),
  ('mission-be19-12-o1', 'mission-be19-12', 1, 'Triage the unvalidated input', 'Debug the endpoint the review flagged for accepting any input with no validation.'),
  ('mission-be19-12-o2', 'mission-be19-12', 2, 'Triage the CORS policy', 'Debug the CORS configuration the review flagged as its second finding.'),
  ('mission-be19-12-o3', 'mission-be19-12', 3, 'Triage the missing rate limit', 'Find the evidence that shows the missing rate limit is a systemic gap, not one overlooked endpoint.'),
  ('mission-be19-12-o4', 'mission-be19-12', 4, 'Close the review', 'Synthesize all three findings into what the remediation covers.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-be19-01-o1-c1', 'mission-be19-01-o1', 1, 'investigation', 'Which evidence identifies the actual threat this endpoint failed to model, not just where it eventually showed up?', '{"evidence":[{"id":"ev1","label":"Endpoint description","detail":"POST /api/permits/:id/status accepts a status value and updates a city permit record, callable by any authenticated user."},{"id":"ev2","label":"Code review comment","detail":"A comment above the handler reads: any authenticated user is a legitimate caller, no further checks needed."},{"id":"ev3","label":"Access log","detail":"A single authenticated low-privilege account called this endpoint on permits it never applied for and had no role tied to."}],"question":"Which evidence identifies the actual threat this endpoint failed to model, not just where it eventually showed up?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),

  ('mission-be19-02-o1-c1', 'mission-be19-02-o1', 1, 'code_debugging', 'This handler passes request body fields straight into createPermit with no checks at all. Which line is where validation needs to happen and currently doesn''t?', '{"language":"typescript","code":"app.post(\"/api/permits\", (req, res) => {\n  const { applicantName, district } = req.body;\n  const permit = createPermit(applicantName, district);\n  res.json(permit);\n});","question":"This handler passes request body fields straight into createPermit with no checks at all. Which line is where validation needs to happen and currently doesn''t?"}'::jsonb, '{"requiredLineIds":["  const { applicantName, district } = req.body;"]}'::jsonb),

  ('mission-be19-03-o1-c1', 'mission-be19-03-o1', 1, 'code_debugging', 'A request with permitId set to 0 OR 1=1 returns every permit instead of just one. Which line is the actual vulnerability?', '{"language":"typescript","code":"const query = \"SELECT * FROM permits WHERE id = \" + permitId;\nconst result = await db.query(query);","question":"A request with permitId set to 0 OR 1=1 returns every permit instead of just one. Which line is the actual vulnerability?"}'::jsonb, '{"requiredLineIds":["const query = \"SELECT * FROM permits WHERE id = \" + permitId;"]}'::jsonb),
  ('mission-be19-03-o2-c1', 'mission-be19-03-o2', 1, 'multiple_choice', 'Which change actually prevents this class of injection, not just this one instance of it?', '{"question":"Which change actually prevents this class of injection, not just this one instance of it?","options":[{"id":"a","text":"Manually escape special characters in the input string before concatenating"},{"id":"b","text":"Use a parameterized query with the input passed as a bound parameter, so the database always treats it as data, never as part of the SQL itself"},{"id":"c","text":"Reject any input longer than 50 characters"},{"id":"d","text":"Log the query before running it"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be19-04-o1-c1', 'mission-be19-04-o1', 1, 'code_debugging', 'A request with password set to a JSON operator object instead of a real password string authenticates successfully against any username. Which line is where that object reaches the query unchecked?', '{"language":"javascript","code":"async function login(req, res) {\n  const { username, password } = req.body;\n  const user = await db.collection(\"users\").findOne({ username, password });\n  res.json({ authenticated: !!user });\n}","question":"A request with password set to a JSON operator object instead of a real password string authenticates successfully against any username. Which line is where that object reaches the query unchecked?"}'::jsonb, '{"requiredLineIds":["  const user = await db.collection(\"users\").findOne({ username, password });"]}'::jsonb),

  ('mission-be19-05-o1-c1', 'mission-be19-05-o1', 1, 'code_debugging', 'Browsers reject this exact combination at runtime, but the intent is the dangerous configuration this Act keeps warning about. Which line is the actual problem?', '{"language":"javascript","code":"app.use(cors({\n  origin: \"*\",\n  credentials: true,\n}));","question":"Browsers reject this exact combination at runtime, but the intent is the dangerous configuration this Act keeps warning about. Which line is the actual problem?"}'::jsonb, '{"requiredLineIds":["  origin: \"*\","]}'::jsonb),
  ('mission-be19-05-o2-c1', 'mission-be19-05-o2', 1, 'investigation', 'Which evidence explains the actual mechanism letting an arbitrary origin through, not just an example of it happening?', '{"evidence":[{"id":"ev1","label":"CORS middleware","detail":"The origin function reads the incoming Origin request header and returns it unchanged as the allowed origin for every request, with no allowlist check at all."},{"id":"ev2","label":"Traffic sample","detail":"A request from evil-mirror.example successfully received an Access-Control-Allow-Origin response header matching evil-mirror.example."},{"id":"ev3","label":"Team note","detail":"This was originally written to support an unknown number of city partner subdomains without maintaining a list."}],"question":"Which evidence explains the actual mechanism letting an arbitrary origin through, not just an example of it happening?"}'::jsonb, '{"requiredEvidenceIds":["ev1"]}'::jsonb),

  ('mission-be19-06-o1-c1', 'mission-be19-06-o1', 1, 'multiple_choice', 'A state-changing endpoint accepts a request based on a valid session cookie alone, with no other check. What''s the actual gap?', '{"question":"A state-changing endpoint -- POST /api/permits/:id/revoke -- accepts the request based on a valid session cookie alone, with no other check. What''s the actual gap?","options":[{"id":"a","text":"Nothing, a valid session cookie is proof of an authenticated user"},{"id":"b","text":"A malicious page on another site can trigger this exact request from a logged-in user''s browser, and the cookie will be attached automatically -- the endpoint has no way to tell a legitimate request from a forged one"},{"id":"c","text":"The endpoint should use GET instead of POST"},{"id":"d","text":"This is only a problem if the user is not authenticated"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be19-07-o1-c1', 'mission-be19-07-o1', 1, 'investigation', 'Which evidence is the actual root cause enabling this, not just proof that it''s exploitable?', '{"evidence":[{"id":"ev1","label":"Feature description","detail":"The report-generation service accepts an imageUrl field and fetches it server-side to embed in a PDF."},{"id":"ev2","label":"Fetch code","detail":"The fetch call passes imageUrl directly to the HTTP client with no check against its host or IP range."},{"id":"ev3","label":"Test result","detail":"Setting imageUrl to an internal metadata address successfully returns internal instance metadata inside the generated PDF."}],"question":"Which evidence is the actual root cause enabling this, not just proof that it''s exploitable?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),

  ('mission-be19-08-o1-c1', 'mission-be19-08-o1', 1, 'drag_and_drop', 'Match each secure header to the category of attack it closes off.', '{"items":[{"id":"h1","text":"Strict-Transport-Security"},{"id":"h2","text":"X-Content-Type-Options: nosniff"},{"id":"h3","text":"X-Frame-Options: DENY"},{"id":"h4","text":"Content-Security-Policy"}],"targets":[{"id":"t1","label":"Tells the browser to only ever connect over HTTPS, even if a link says http://"},{"id":"t2","label":"Stops the browser from guessing a file''s type differently than the declared Content-Type, closing off a class of upload-based attacks"},{"id":"t3","label":"Prevents the page from being loaded inside a frame on another site, blocking clickjacking"},{"id":"t4","label":"Explicitly lists which sources scripts, styles and other resources are allowed to load from"}]}'::jsonb, '{"correctMapping":{"h1":"t1","h2":"t2","h3":"t3","h4":"t4"}}'::jsonb),

  ('mission-be19-09-o1-c1', 'mission-be19-09-o1', 1, 'investigation', 'Which evidence explains the actual root cause behind both the load test result and the incident, not just one instance of it?', '{"evidence":[{"id":"ev1","label":"Load test","detail":"10,000 requests to /api/auth/login from a single IP in one minute all reached the handler and were processed individually."},{"id":"ev2","label":"Config check","detail":"No rate-limiting middleware is registered anywhere in the request pipeline."},{"id":"ev3","label":"Incident report","detail":"A credential-stuffing attempt tried 40,000 password combinations against one account over three hours before anyone noticed."}],"question":"Which evidence explains the actual root cause behind both the load test result and the incident, not just one instance of it?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),
  ('mission-be19-09-o2-c1', 'mission-be19-09-o2', 1, 'code_debugging', 'Every other public route is protected, but the most sensitive one isn''t. Which line is missing the fix?', '{"language":"javascript","code":"const limiter = rateLimit({ windowMs: 60000, max: 100 });\napp.use(\"/api/public\", limiter);\napp.use(\"/api/auth\", express.json());","question":"Every other public route is protected, but the most sensitive one isn''t. Which line is missing the fix?"}'::jsonb, '{"requiredLineIds":["app.use(\"/api/auth\", express.json());"]}'::jsonb),

  ('mission-be19-10-o1-c1', 'mission-be19-10-o1', 1, 'code_debugging', 'This login flow lets an attacker enumerate valid usernames one guess at a time. Which line leaks that information?', '{"language":"typescript","code":"if (!userExists) {\n  return res.status(401).json({ error: \"No account found for that username\" });\n}\nif (!passwordMatches) {\n  return res.status(401).json({ error: \"Incorrect password\" });\n}","question":"This login flow lets an attacker enumerate valid usernames one guess at a time. Which line leaks that information?"}'::jsonb, '{"requiredLineIds":["  return res.status(401).json({ error: \"No account found for that username\" });"]}'::jsonb),

  ('mission-be19-11-o1-c1', 'mission-be19-11-o1', 1, 'code_debugging', 'This live API key is now permanently in git history, readable by anyone with repo access, past or present. Which line needs to move to an environment variable or secret manager?', '{"language":"typescript","code":"const stripeClient = new StripeClient({\n  apiKey: \"hardcoded-demo-key-not-a-credential\",\n  timeout: 5000,\n});","question":"This live API key is now permanently in git history, readable by anyone with repo access, past or present. Which line needs to move to an environment variable or secret manager?"}'::jsonb, '{"requiredLineIds":["  apiKey: \"hardcoded-demo-key-not-a-credential\","]}'::jsonb),
  ('mission-be19-11-o2-c1', 'mission-be19-11-o2', 1, 'investigation', 'Which evidence explains why these vulnerabilities are actually exploitable in Forge''s case, not just present in the dependency tree?', '{"evidence":[{"id":"ev1","label":"Dependency audit","detail":"A dependency scan lists 14 known vulnerabilities across dependencies, 3 of them rated critical, none patched in over 8 months."},{"id":"ev2","label":"Team habit","detail":"Dependency versions are pinned exactly and never bumped except when a new feature explicitly requires it."},{"id":"ev3","label":"Incident correlation","detail":"One of the critical vulnerabilities has a public exploit matching the exact library version Forge still runs in production."}],"question":"Which evidence explains why these vulnerabilities are actually exploitable in Forge''s case, not just present in the dependency tree?"}'::jsonb, '{"requiredEvidenceIds":["ev3"]}'::jsonb),

  ('mission-be19-12-o1-c1', 'mission-be19-12-o1', 1, 'code_debugging', 'The review flagged this endpoint for accepting any string as a permit status, including values that break downstream reporting. Which line is missing validation against a fixed set of allowed statuses?', '{"language":"typescript","code":"app.post(\"/api/permits/:id/status\", (req, res) => {\n  const { status } = req.body;\n  updatePermitStatus(req.params.id, status);\n  res.json({ updated: true });\n});","question":"The review flagged this endpoint for accepting any string as a permit status, including values that break downstream reporting. Which line is missing validation against a fixed set of allowed statuses?"}'::jsonb, '{"requiredLineIds":["  const { status } = req.body;"]}'::jsonb),
  ('mission-be19-12-o2-c1', 'mission-be19-12-o2', 1, 'code_debugging', 'The review''s second finding: this configuration reflects any requesting origin back as allowed, with credentials enabled. Which line is the actual misconfiguration?', '{"language":"javascript","code":"app.use(cors({\n  origin: true,\n  credentials: true,\n}));","question":"The review''s second finding: this configuration reflects any requesting origin back as allowed, with credentials enabled. Which line is the actual misconfiguration?"}'::jsonb, '{"requiredLineIds":["  origin: true,"]}'::jsonb),
  ('mission-be19-12-o3-c1', 'mission-be19-12-o3', 1, 'investigation', 'Which evidence shows this is a systemic gap across the API, not just one overlooked endpoint?', '{"evidence":[{"id":"ev1","label":"Endpoint list","detail":"/api/permits/search, /api/auth/login and /api/reports/generate all process every request they receive with no per-IP or per-account limit."},{"id":"ev2","label":"Review finding","detail":"The external review flagged this as a finding across the entire public API surface, not one isolated endpoint."},{"id":"ev3","label":"Load capability","detail":"A single client was able to sustain 500 requests per second against the login endpoint for over ten minutes without being throttled."}],"question":"Which evidence shows this is a systemic gap across the API, not just one overlooked endpoint?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),
  ('mission-be19-12-o4-c1', 'mission-be19-12-o4', 1, 'boss_encounter', 'Having triaged all three findings, state what the remediation actually covers.', '{"stages":[{"objectiveRef":"mission-be19-12-o1","label":"Triage the unvalidated input"},{"objectiveRef":"mission-be19-12-o2","label":"Triage the CORS policy"},{"objectiveRef":"mission-be19-12-o3","label":"Triage the missing rate limit"}],"task":"Having triaged all three findings, state what the remediation actually covers: validating status values against a fixed allowlist, replacing the reflective CORS policy with an explicit origin allowlist, and applying rate limiting across the entire public API surface, not just one endpoint -- ordinary security debt, fully patched."}'::jsonb, '{"requiredObjectiveIds":["mission-be19-12-o1","mission-be19-12-o2","mission-be19-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-be19-01-o1-c1', 'orientation', 'Two of these describe the situation. One describes the assumption underneath it.', 10, 1),
  ('mission-be19-01-o1-c1', 'concept', 'A threat model asks what happens when a piece of trust is abused -- the incident in the access log is what happens after that question never gets asked.', 20, 2),
  ('mission-be19-01-o1-c1', 'solution', 'ev2: the comment stating no further checks are needed is the actual unexamined trust assumption -- ev1 just describes the endpoint, ev3 is the resulting incident.', 30, 3),

  ('mission-be19-02-o1-c1', 'orientation', 'Validation has to happen at the exact point untrusted data first enters the function.', 10, 1),
  ('mission-be19-02-o1-c1', 'concept', 'Reading fields off req.body is the trust-boundary crossing itself -- nothing has checked their shape, type or content by the time createPermit receives them.', 20, 2),
  ('mission-be19-02-o1-c1', 'solution', 'The destructuring line takes applicantName and district straight from the request body with no validation before they''re used.', 30, 3),

  ('mission-be19-03-o1-c1', 'orientation', 'The attacker''s input doesn''t need quotes here -- it just needs to be part of the same string as the query.', 10, 1),
  ('mission-be19-03-o1-c1', 'concept', 'String concatenation makes user input part of the SQL text itself, so "0 OR 1=1" isn''t treated as a value being compared -- it''s treated as SQL.', 20, 2),
  ('mission-be19-03-o1-c1', 'solution', 'The query is built by concatenating permitId directly into the SQL string -- that''s the line the injected condition rides in on.', 30, 3),
  ('mission-be19-03-o2-c1', 'orientation', 'The fix has to change how the database interprets input, not just how the input looks.', 10, 1),
  ('mission-be19-03-o2-c1', 'solution', 'b: a parameterized query keeps the boundary between SQL and data hard, no matter what the input contains -- escaping and length limits are both workarounds that can still be bypassed.', 20, 2),

  ('mission-be19-04-o1-c1', 'orientation', 'The destructured password field is used exactly as received -- nothing checks its type before the query runs.', 10, 1),
  ('mission-be19-04-o1-c1', 'concept', 'A document-database driver that accepts a whole object where it expected a plain value can end up executing an operator instead of comparing to a literal.', 20, 2),
  ('mission-be19-04-o1-c1', 'solution', 'findOne({ username, password }) passes password straight into the query with no type check -- a driver that accepts an operator object there executes it instead of comparing to a literal.', 30, 3),

  ('mission-be19-05-o1-c1', 'orientation', 'Two settings here are each fine alone. Combined, they mean something dangerous.', 10, 1),
  ('mission-be19-05-o1-c1', 'concept', 'Allowing every origin is meant for public, unauthenticated APIs -- pairing it with credentials assumes trust that a wildcard origin can never actually establish.', 20, 2),
  ('mission-be19-05-o1-c1', 'solution', 'origin: "*" is the actual problem -- combined with credentials: true it expresses ''trust every website with a logged-in user''s cookies,'' which is never the intent.', 30, 3),
  ('mission-be19-05-o2-c1', 'orientation', 'The traffic sample is one instance. The middleware code is the rule that produces every instance like it.', 10, 1),
  ('mission-be19-05-o2-c1', 'concept', 'Reflecting the Origin header back unchanged behaves like an allowlist containing every origin that has ever asked -- it isn''t a real allowlist at all.', 20, 2),
  ('mission-be19-05-o2-c1', 'solution', 'ev1: the origin function echoes back whatever Origin header it receives with no check against a real allowlist -- that''s the mechanism, not just one example of it firing.', 30, 3),

  ('mission-be19-06-o1-c1', 'orientation', 'Ask what a completely different website could get a logged-in user''s browser to do without the user ever knowing.', 10, 1),
  ('mission-be19-06-o1-c1', 'solution', 'b: a cookie alone doesn''t prove the request was intentional -- any site can trigger it and the browser attaches the cookie automatically, so the endpoint can''t tell a real request from a forged one.', 20, 2),

  ('mission-be19-07-o1-c1', 'orientation', 'The test result proves the gap exists. It doesn''t explain what let it exist.', 10, 1),
  ('mission-be19-07-o1-c1', 'concept', 'Passing a user-supplied URL straight to an HTTP client with no host or IP check treats every destination as equally trustworthy, including addresses that were never meant to be reachable from outside.', 20, 2),
  ('mission-be19-07-o1-c1', 'solution', 'ev2: the fetch call has no check against the URL''s host or IP range before requesting it -- that''s the actual root cause the test result only demonstrates.', 30, 3),

  ('mission-be19-08-o1-c1', 'orientation', 'One header is about the connection itself. One is about MIME sniffing. One is about framing. One is about resource sources.', 10, 1),
  ('mission-be19-08-o1-c1', 'solution', 'HSTS -> HTTPS-only, X-Content-Type-Options -> stops MIME-sniffing, X-Frame-Options -> stops clickjacking, CSP -> allowlists resource sources.', 20, 2),

  ('mission-be19-09-o1-c1', 'orientation', 'The load test and the incident are both things that happened. One piece of evidence explains why nothing stopped either of them.', 10, 1),
  ('mission-be19-09-o1-c1', 'concept', 'Without rate-limiting middleware registered anywhere, every request reaches the handler regardless of volume -- there''s no mechanism anywhere in the pipeline that could have stopped it.', 20, 2),
  ('mission-be19-09-o1-c1', 'solution', 'ev2: no rate-limiting middleware exists anywhere in the pipeline -- that absence is the root cause behind both the load test and the incident.', 30, 3),
  ('mission-be19-09-o2-c1', 'orientation', 'Compare which routes get the limiter applied and which one is set up differently.', 10, 1),
  ('mission-be19-09-o2-c1', 'solution', 'app.use("/api/auth", express.json()) never has the limiter applied to it -- the most sensitive route is the one left unprotected.', 20, 2),

  ('mission-be19-10-o1-c1', 'orientation', 'Two different error messages for two different failure reasons is exactly the leak.', 10, 1),
  ('mission-be19-10-o1-c1', 'concept', 'If the username-not-found case and the wrong-password case return different messages, an attacker can tell which usernames are real just by watching which message comes back.', 20, 2),
  ('mission-be19-10-o1-c1', 'solution', 'The "No account found for that username" message confirms a username doesn''t exist -- both branches should return the same generic message instead.', 30, 3),

  ('mission-be19-11-o1-c1', 'orientation', 'Anything committed to git stays in its history even after the line is later removed or changed.', 10, 1),
  ('mission-be19-11-o1-c1', 'concept', 'A secret hardcoded in source is a secret anyone with repo access, past or present, can read -- rotating it doesn''t remove it from history, only a real secret manager keeps it out of the repo entirely.', 20, 2),
  ('mission-be19-11-o1-c1', 'solution', 'apiKey: "sk_live_..." is a live credential written directly into source -- it needs to come from an environment variable or secret manager instead.', 30, 3),
  ('mission-be19-11-o2-c1', 'orientation', 'A vulnerability existing in a dependency and a vulnerability being exploitable against you are two different claims.', 10, 1),
  ('mission-be19-11-o2-c1', 'concept', 'A public exploit that matches the exact version still running in production is what turns a listed CVE into an actual, present risk, not just a theoretical one.', 20, 2),
  ('mission-be19-11-o2-c1', 'solution', 'ev3: a public exploit matching the exact library version Forge runs in production is what makes this exploitable right now, not just listed.', 30, 3),

  ('mission-be19-12-o1-c1', 'orientation', 'The status value is used exactly as received, with nothing checking it against what a permit status is actually allowed to be.', 10, 1),
  ('mission-be19-12-o1-c1', 'solution', 'status is destructured from req.body and passed straight to updatePermitStatus with no check against a fixed allowlist of valid statuses.', 20, 2),
  ('mission-be19-12-o2-c1', 'orientation', 'This is the same shape of bug as earlier this Act, just with a different setting name.', 10, 1),
  ('mission-be19-12-o2-c1', 'solution', 'origin: true reflects every requesting origin back as allowed -- combined with credentials: true it''s the same dangerous combination as before, expressed differently.', 20, 2),
  ('mission-be19-12-o3-c1', 'orientation', 'The load capability is one demonstration. The review''s own framing tells you the scope.', 10, 1),
  ('mission-be19-12-o3-c1', 'solution', 'ev2: the review explicitly flagged this across the entire public API surface, confirming it as systemic rather than one endpoint''s oversight.', 20, 2),
  ('mission-be19-12-o4-c1', 'orientation', 'Line up each fix with the finding it actually closes -- validation, CORS, and rate limiting are three separate patches, not one.', 15, 1),
  ('mission-be19-12-o4-c1', 'solution', 'A status allowlist, an explicit CORS origin allowlist, and rate limiting applied across the full public API surface -- three ordinary fixes for three ordinary findings, none of them the pattern.', 25, 2);
